def weighted_distance_sums(n: int, edges: list[list[int]], w: list[int]) -> list[int]:
    if n == 0:
        return []
    adj = [[] for _ in range(n)]
    for a, b in edges:
        adj[a].append(b)
        adj[b].append(a)

    parent = [-1] * n
    order = [0] * n
    stack = [0]
    seen = 0
    parent[0] = n
    while stack:
        v = stack.pop()
        order[seen] = v
        seen += 1
        for u in adj[v]:
            if u != parent[v]:
                parent[u] = v
                stack.append(u)

    sub_w = [0] * n
    for i in range(n - 1, -1, -1):
        v = order[i]
        sw = w[v]
        for u in adj[v]:
            if parent[u] == v:
                sw += sub_w[u]
        sub_w[v] = sw

    ans = [0] * n
    ans[0] = 0
    for u in adj[0]:
        if parent[u] == 0:
            ans[0] += _subtree_dist(u, parent, adj, sub_w, w)

    total = sub_w[0]
    for i in range(n):
        v = order[i]
        base = ans[v]
        for u in adj[v]:
            if parent[u] == v:
                ans[u] = base + total - 2 * sub_w[u]
    return ans


def _subtree_dist(v, parent, adj, sub_w, w):
    acc = sub_w[v]
    for u in adj[v]:
        if parent[u] == v:
            acc += _subtree_dist(u, parent, adj, sub_w, w)
    return acc
